const CTA_ID = 'cta-contact-btn-wrapper';
if (document.getElementById(CTA_ID)) return;

const h1 = element.querySelector('h1.article-title');
if (!h1) return;

const wrapper = document.createElement('div');
wrapper.id = CTA_ID;
wrapper.style.cssText = `
  margin: 18px 0 10px 0;
  display: flex;
  align-items: center;
  gap: 12px;
`;

const btn = document.createElement('a');
btn.href = 'https://support.fandom.com/hc/en-us/requests/new?ticket_form_id=360000931354&tf_360017817454=i_want_a_feature_or_extension_turned_on';
btn.target = '_self';
btn.textContent = '📩 Contact Us — Request a Feature or Extension';
btn.style.cssText = `
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 26px;
  background: linear-gradient(135deg, #2563eb 0%, #1e40af 100%);
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
  font-family: inherit;
  text-decoration: none;
  border-radius: 8px;
  box-shadow: 0 4px 14px rgba(37,99,235,0.45);
  letter-spacing: 0.3px;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
  border: none;
  cursor: pointer;
`;

btn.addEventListener('mouseenter', () => {
  btn.style.background = 'linear-gradient(135deg, #1d4ed8 0%, #1e3a8a 100%)';
  btn.style.boxShadow = '0 6px 20px rgba(37,99,235,0.6)';
  btn.style.transform = 'translateY(-2px)';
});
btn.addEventListener('mouseleave', () => {
  btn.style.background = 'linear-gradient(135deg, #2563eb 0%, #1e40af 100%)';
  btn.style.boxShadow = '0 4px 14px rgba(37,99,235,0.45)';
  btn.style.transform = 'translateY(0)';
});

const label = document.createElement('span');
label.textContent = 'Can\'t find what you need? We\'re here to help.';
label.style.cssText = `
  font-size: 13px;
  color: #6b7280;
  font-style: italic;
`;

wrapper.appendChild(btn);
wrapper.appendChild(label);
h1.insertAdjacentElement('afterend', wrapper);
